def find_peak_linear(a: list[int]) -> int:
    n = len(a)
    for i in range(n):
        left = a[i - 1] if i > 0 else float("-inf")
        right = a[i + 1] if i < n - 1 else float("-inf")
        if a[i] > left and a[i] > right:
            return i
    return -1

def find_peak(a: list[int]) -> int:
    lo, hi = 0, len(a) - 1
    while lo < hi:
        mid = lo + (hi - lo) // 2
        if a[mid] < a[mid + 1]:
            lo = mid + 1
        else:
            hi = mid
    return lo
